        // Admissible domain: at least one call, at most 5 to keep state exploration reasonable
        bound(numCalls, 1, 5);

        // Track expected pot based on calls made
        uint256 expectedPot = 0;
        bool allSucceeded = true;

        for (uint256 i = 0; i < numCalls; i++) {
            address caller = address(uint160(uint256(keccak256(abi.encodePacked("caller", i)))));
