            vm.prank(caller);
            try c.play{value: TICKET_AMOUNT}() {
                // Call succeeded: either win (pot reset to 0 after payout) or nothing (random != 0)
                // In reference C, a successful call that does not pay out still adds TICKET_AMOUNT to pot
                // Since we cannot predict random outcome, we cannot compute expectedPot without knowing random.
                // The property must hold for all inputs regardless of random.
            } catch {
                allSucceeded = false;
                break;
            }
        }

        // General rule: after any sequence of calls, if no call reverted,
        // the pot must equal the total ether sent in (numCalls * TICKET_AMOUNT) minus any payouts.
        // Payouts only happen on random == 0, and they reset pot to 0.
        // In reference C, pot is incremented by TICKET_AMOUNT on every non-reverting call,
        // and reset to 0 only on a win (with payout).
