        // So M fails the invariant after a non-win call. C always satisfies.

        // We need to force at least one call that succeeds. We cannot force random outcome.
        // But if we make many calls, some may succeed (non-win). The fuzzer will find one.
        // And the assertion will fail when a non-win occurs because balance != pot.
        // This is a valid universal property that C always satisfies, M sometimes violates.

        // Assert that for every state reachable, address(c).balance == c.pot().
        // We'll check after setup and after some calls.

        assertEq(address(c).balance, c.pot(), "invariant: balance equals pot");

        // Then make some calls to explore reachable states
        for (uint256 i = 0; i < numCalls; i++) {
            address caller = address(uint160(uint256(keccak256(abi.encodePacked("caller", i)))));
            vm.deal(caller, TICKET_AMOUNT);
            vm.prank(caller);
            try c.play{value: TICKET_AMOUNT}() {
                // call succeeded
            } catch {
                // call failed, ignore
            }
            // After each call, check invariant again
            assertEq(address(c).balance, c.pot(), "invariant: balance equals pot");
        }
    }
}

