                totalPaid = 0; // pot becomes 0
            } catch {
                // If play reverts (e.g. due to insufficient msg.value, but we always send 10),
                // pot should not change; we still track totalPaid only for successful calls
                // In reality play() cannot revert if we send exactly 10, but keep try/catch just in case
            }
